function todayParts() {
  const now = new Date();
  return { d: now.getDate(), m: now.getMonth() + 1, y: now.getFullYear(), date: now };
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

function todayStr() {
  const t = todayParts();
  return pad2(t.d) + '/' + pad2(t.m) + '/' + t.y;
}

function getChatId() {
  return $('Telegram').item.json.message.chat.id;
}

function cleanText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value !== 'string') return JSON.stringify(value);
  return value
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/<think>[\s\S]*/gi, '')
    .replace(new RegExp(String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96) + '(?:json)?', 'gi'), '')
    .replace(new RegExp(String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96), 'g'), '')
    .trim();
}

function extractJsonCandidate(text) {
  const cleaned = cleanText(text);
  if (!cleaned) return '';
  const start = cleaned.search(/[\[{]/);
  if (start === -1) return cleaned;
  const open = cleaned[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < cleaned.length; i++) {
    const ch = cleaned[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\') { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === open) depth++;
    if (ch === close) depth--;
    if (depth === 0) return cleaned.slice(start, i + 1);
  }
  return cleaned.slice(start);
}

function getAiText(item) {
  const candidates = [
    item.output, item.text, item.content, item.response, item.result,
    item.message && item.message.content,
    item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content,
  ];
  for (const candidate of candidates) {
    if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') return candidate;
  }
  return '';
}

function parseAiJson(item) {
  const raw = getAiText(item);
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
  const candidate = extractJsonCandidate(raw);
  if (!candidate) throw new Error('AI_NO_JSON');
  return JSON.parse(candidate);
}

function str(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  const text = String(value).trim();
  return text || fallback;
}

function normalizeDate(value) {
  const text = str(value);
  return text && text.toLowerCase() !== 'null' ? text : todayStr();
}

function parseDate(value) {
  const text = str(value);
  let m = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));
  m = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return null;
}

// Tanggal versi panjang: "7 Juli 2026"
function tanggalPanjang(dateText) {
  const bulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
  const d = parseDate(dateText) || new Date();
  return d.getDate() + ' ' + bulan[d.getMonth()] + ' ' + d.getFullYear();
}

function parseIndoWords(text) {
  let t = String(text || '').toLowerCase();
  t = t.replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) return 0;
  t = ' ' + t + ' ';
  t = t.replace(/\bseratus\b/g, ' satu ratus ').replace(/\bseribu\b/g, ' satu ribu ').replace(/\bsejuta\b/g, ' satu juta ').replace(/\bsemiliar\b/g, ' satu miliar ');
  const words = t.trim().split(/\s+/).filter(Boolean);
  const num = { satu:1,dua:2,tiga:3,empat:4,lima:5,enam:6,tujuh:7,delapan:8,sembilan:9 };
  let total = 0, group = 0, small = 0, matched = false;
  for (const w of words) {
    if (num[w] != null) { small += num[w]; matched = true; }
    else if (w === 'sepuluh') { group += 10; matched = true; }
    else if (w === 'sebelas') { group += 11; matched = true; }
    else if (w === 'belas') { group += 10 + small; small = 0; matched = true; }
    else if (w === 'puluh') { group += 10 * (small || 0); small = 0; matched = true; }
    else if (w === 'ratus') { group += 100 * (small || 1); small = 0; matched = true; }
    else if (w === 'ribu') { total += 1000 * ((group + small) || 1); group = 0; small = 0; matched = true; }
    else if (w === 'juta') { total += 1e6 * ((group + small) || 1); group = 0; small = 0; matched = true; }
    else if (w === 'miliar' || w === 'milyar') { total += 1e9 * ((group + small) || 1); group = 0; small = 0; matched = true; }
    else if (w === 'nol') { matched = true; }
  }
  return matched ? (total + group + small) : 0;
}

function parseNumericAmount(s) {
  const withUnit = s.match(/(-?\d[\d.,]*)\s*(miliar|milyar|juta|jt|ribu|rb|k)(?![a-z])/i);
  let raw, unit;
  if (withUnit) { raw = withUnit[1]; unit = withUnit[2].toLowerCase(); }
  else {
    const plain = s.match(/-?\d[\d.,]*/);
    if (!plain) return 0;
    raw = plain[0]; unit = '';
  }
  let mult = 1;
  if (/miliar|milyar/.test(unit)) mult = 1e9;
  else if (/juta|jt/.test(unit)) mult = 1e6;
  else if (/ribu|rb|k/.test(unit)) mult = 1e3;
  let numTxt;
  if (mult > 1) {
    if (raw.includes(',')) numTxt = raw.replace(/\./g, '').replace(',', '.');
    else if (raw.includes('.')) {
      const parts = raw.split('.');
      const last = parts[parts.length - 1];
      numTxt = (parts.length === 2 && last.length !== 3) ? raw : raw.replace(/\./g, '');
    } else numTxt = raw;
  } else {
    numTxt = raw.replace(/[.,]/g, '');
  }
  const n = Number(numTxt);
  return Number.isFinite(n) ? Math.max(0, Math.round(n * mult)) : 0;
}

function nominal(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return Math.max(0, Math.round(value));
  let s = String(value == null ? '' : value).toLowerCase().trim();
  if (!s) return 0;
  s = s.replace(/rp\.?/gi, ' ').replace(/rupiah/gi, ' ').replace(/idr/gi, ' ').trim();
  if (/[0-9]/.test(s)) return parseNumericAmount(s);
  const w = parseIndoWords(s);
  return w > 0 ? Math.round(w) : 0;
}

function jenis(value, fallback = 'Pengeluaran') {
  return /^pemasukan$/i.test(str(value)) ? 'Pemasukan' : fallback;
