  const value = nominal(row.Nominal || row.nominal);
  const rowJenis = str(row.Jenis || row.jenis);
  if (/pemasukan/i.test(rowJenis)) pemasukan += value;
  if (/pengeluaran/i.test(rowJenis)) pengeluaran += value;
  count++;
}

