// ============================================================
// KONFIGURASI - ubah sesuai kebutuhan (hanya bagian ini)
const MARGIN = 0.30;              // 0.30 = margin profit 30%
const KOLOM_NOMINAL = 'Nominal';  // nama kolom nominal di sheet
const KOLOM_TANGGAL = 'Tanggal';  // nama kolom tanggal di sheet
const KOLOM_JENIS   = 'Jenis';    // nama kolom jenis di sheet
// ============================================================

function pad2(v) { return String(v).padStart(2, '0'); }

function parseDate(value) {
  const text = String(value || '').trim();
  let m = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));
  m = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return null;
}

function isToday(dateStr) {
  const d = parseDate(dateStr);
  if (!d) return false;
  const now = new Date();
  return d.getDate() === now.getDate() && d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
}

function parseNominal(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return Math.max(0, Math.round(value));
  const text = String(value || '').replace(/rp/gi, '').replace(/[^0-9]/g, '');
  const n = Number(text);
  return Number.isFinite(n) ? Math.max(0, n) : 0;
}

function formatRp(value) {
  return 'Rp' + Math.round(value || 0).toLocaleString('id-ID');
}

const rows = $input.all();
const now = new Date();
const tanggal = now.toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const tanggalShort = pad2(now.getDate()) + '/' + pad2(now.getMonth() + 1) + '/' + now.getFullYear();

// Filter: hanya Pemasukan dengan tanggal hari ini
const orders = rows
  .filter(r => {
    const jenis = String(r.json[KOLOM_JENIS] || '').toLowerCase();
    return isToday(r.json[KOLOM_TANGGAL]) && jenis.includes('pemasukan');
  })
  .map(r => parseNominal(r.json[KOLOM_NOMINAL]))
  .filter(v => v > 0);

// Jika tidak ada transaksi hari ini
if (orders.length === 0) {
  return [{ json: {
    tanggal, tanggal_short: tanggalShort,
    total_order: 0,
    total_revenue_raw: 0,  total_revenue: 'Rp0',
    estimasi_modal_raw: 0, estimasi_modal: 'Rp0',
    estimasi_profit_raw: 0, estimasi_profit: 'Rp0',
    average_order_raw: 0,  average_order: 'Rp0',
    order_terbesar_raw: 0, order_terbesar: 'Rp0',
    order_terkecil_raw: 0, order_terkecil: 'Rp0',
    margin_persen: Math.round(MARGIN * 100),
    ada_data: false
  }}];
}

// Hitung 7 metrik
const totalRevenue   = orders.reduce((a, b) => a + b, 0);
const totalOrder     = orders.length;
const averageOrder   = totalRevenue / totalOrder;
const orderTerbesar  = Math.max(...orders);
const orderTerkecil  = Math.min(...orders);
const estimasiModal  = totalRevenue * (1 - MARGIN);
const estimasiProfit = totalRevenue * MARGIN;

return [{ json: {
  tanggal, tanggal_short: tanggalShort,
  total_order: totalOrder,
  total_revenue_raw:   Math.round(totalRevenue),   total_revenue:   formatRp(totalRevenue),
